#!/usr/bin/env python3
"""Make src/ned/nim/nimapis.nim: which standard-library names and modules each Nim release added.

ned warns when code uses one that is newer than the Nim a package says it needs (`requires "nim >= …"` in its
.nimble, or nim.minVersion). Run it with the `lib` folders of the releases, oldest first:

    python3 .github/ci/nimapis.py v1.0.0=/path/Nim-1.0.0/lib v1.2.0=… … v2.2.12=… > src/ned/nim/nimapis.nim

(`git clone --depth 1 --branch v2.2.12 --filter=blob:none --sparse https://github.com/nim-lang/Nim` then
`git sparse-checkout set lib` gets one.) A name counts as new only when no earlier release marks it exported
anywhere (`name*`), so a moved or renamed declaration is never reported; a module counts as new when no earlier
release has a module of that name.
"""
import os, re, sys

DECL = re.compile(r'^\s*(?:proc|func|iterator|template|macro|converter|method)\s+(`[^`]+`|[A-Za-z_]\w*)\*')
SECT = re.compile(r'^\s*(`[^`]+`|[A-Za-z_]\w*)\*\s*(?:\[[^\]]*\])?\s*(?:\{\..*?\.\})?\s*=')
STAR = re.compile(r'(`[^`]+`|\b[A-Za-z_]\w*)\*')
SKIP = ('private/', 'genode/', 'windows/', 'deprecated/', 'nimhcr', 'nimrtl', 'system/', 'arch/', 'core/')
PUBLIC = ('pure/', 'std/', 'impure/', 'js/', 'packages/', 'wrappers/', 'posix/')

def norm(n):
    n = n.strip('`')
    return n[0] + n[1:].replace('_', '').lower() if n else n

def scan(lib):
    decls, stars, mods = {}, set(), set()
    for root, _, files in os.walk(lib):
        for f in files:
            if not f.endswith('.nim'): continue
            p = os.path.join(root, f)
            rel = os.path.relpath(p, lib).replace(os.sep, '/')
            if rel.startswith(PUBLIC) and not any(s in rel for s in ('private/',)): mods.add(f[:-4])
            names = {}
            with open(p, encoding='utf-8', errors='replace') as fh:
                for line in fh:
                    for m in STAR.finditer(line): stars.add(norm(m.group(1)))
                    m = DECL.match(line) or SECT.match(line)
                    if m: names.setdefault(norm(m.group(1)), m.group(1).strip('`'))
            decls[rel] = names
    return decls, stars, mods

def main():
    rels = []
    for a in sys.argv[1:]:
        v, _, lib = a.partition('=')
        rels.append((v.lstrip('v'), scan(lib)))
    out = ['# ── generated by .github/ci/nimapis.py: the standard-library names and modules each Nim release added',
           '#    (a release step: the release before it, it, modules new in it, "module: names" new in it) ──', '',
           'const NimApiSteps* = [']
    for i in range(1, len(rels)):
        before, (oldd, olds, oldm) = rels[i - 1]
        # (a name or module any earlier release had: not new)
        for j in range(i - 1):
            olds = olds | rels[j][1][1]
            oldm = oldm | rels[j][1][2]
        ver, (newd, _, newm) = rels[i]
        newmods = sorted(newm - oldm)
        bykey = {}
        for rel in sorted(newd):
            if rel.startswith(SKIP) and not rel.startswith('system/'): continue
            if any(s in rel for s in ('private/', 'genode/', 'windows/')): continue
            stem = os.path.basename(rel)[:-4]
            if stem in newmods: continue                       # (its import is reported instead)
            added = [v for k, v in newd[rel].items() if k not in olds]
            if added:
                # (system's parts: one module, `system`, whichever file declares the name)
                key = 'system' if rel.startswith('system/') or rel == 'system.nim' else rel[:-4]
                for a in added:
                    if a not in bykey.setdefault(key, []): bykey[key].append(a)
        if not newmods and not bykey: continue
        body = '\n'.join(k + ': ' + ' '.join(sorted(v)) for k, v in sorted(bykey.items()))
        out.append('  (%s, %s, %s,\n   %s),' % (nimstr(before), nimstr(ver), nimstr(' '.join(newmods)), nimstr(body)))
    out.append(']')
    print('\n'.join(out))

def nimstr(s):
    return '"' + s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n') + '"'

main()
